if(!getCloudConfig())setCloudConfig(CLOUD_CONFIG);
const $=(s)=>document.querySelector(s);
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=(n,d=0)=>n===null||n===undefined||!Number.isFinite(n)?'Pendiente':new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR',minimumFractionDigits:d,maximumFractionDigits:d}).format(n);
const pct=(n)=>n==null?'—':new Intl.NumberFormat('es-ES',{style:'percent',maximumFractionDigits:1}).format(n);
const num=(n,d=2)=>new Intl.NumberFormat('es-ES',{maximumFractionDigits:d}).format(n??0);
const copy=(v)=>structuredClone(v);
const APP_VERSION='10';
const normalizeScenario=(input={})=>adoptFamilyFinancingPlan(normalizeFinanceScenario(input));
const draftKey='casa-ideal.draft.v1';
const draftMetaKey='casa-ideal.draft-meta.v1';
let s=normalizeScenario(), hasLocalDraft=false;
try{const draft=JSON.parse(localStorage.getItem(draftKey));if(draft){s=normalizeScenario(draft);hasLocalDraft=true}}catch{}
// Public examples contain no personal income, debts or names.
if(!s.budget.incomes.length)s.budget.incomes=[{monthly:0,payments:12},{monthly:0,payments:12}];
let currentView='viviendas', cloud=null, cloudRows=[], selected=new Set();
let connectionState='connecting', initialConnection=null, pendingFamilyCode=null, pendingScenarioId=null, reconnectingCloud=null, familyActionBusy=false, familyCodeDraft='';
let housingEditorMode='edit', housingEditorSource=null, savingHousing=false;
let draftDirty=false, draftConflict=null, draftRevision=0, autoSaveTimer=null, cloudSavePromise=null, cloudRefreshPromise=null, cloudGeneration=0, lastSyncedAt=null, cloudSyncError=null, routeAutoJoin=false, cloudScope=null, hasCloudSnapshot=false, draftPendingCreate=false, legacyDraftUnreviewed=hasLocalDraft;
try{const meta=JSON.parse(localStorage.getItem(draftMetaKey));if(meta?.id===s.id){draftDirty=meta?.dirty===true;draftPendingCreate=meta?.pendingCreate===true;legacyDraftUnreviewed=false;}}catch{}
let result=calculateScenario(s);
const views={resumen:['Los números de esta vivienda.','Compara el coste completo de comprar con vuestra vida actual.','Cálculo de vivienda'],compra:['Todo lo que cuesta comprar.','La entrada, los impuestos y los gastos que llegan antes de las llaves.','La casa y la compra'],hipoteca:['Las deudas, con todos sus apellidos.','Hipoteca Sabadell, bonificaciones y préstamo de vuestra madre.','Hipoteca y préstamo'],presupuesto:['Los números de vuestro día a día.','Comprar debe dejar espacio para vivir y para los imprevistos.','Presupuesto familiar'],viviendas:['Vuestras viviendas, una al lado de la otra.','Añade casas o pisos y compara precio, compra y presupuesto mensual completo.','Vista general'],fuentes:['Saber de dónde sale cada número.','Conversación con Sabadell y normativa: cada cosa en su lugar.','Condiciones y fuentes'],familia:['Una decisión compartida.','Guardad vuestras simulaciones y trabajad sobre la misma lista de viviendas.','Compartir en familia']};
const get=(path)=>path.split('.').reduce((o,k)=>o?.[k],s);
const set=(path,value)=>{const a=path.split('.');const k=a.pop();let o=s;for(let i=0;i<a.length;i++){if(!o[a[i]]||typeof o[a[i]]!=='object')o[a[i]]=/^\d+$/.test(a[i+1]||k)?[]:{};o=o[a[i]];}o[k]=value};
function persist(){try{localStorage.setItem(draftKey,JSON.stringify(s));localStorage.setItem(draftMetaKey,JSON.stringify({id:s.id||null,dirty:draftDirty,pendingCreate:draftPendingCreate}));hasLocalDraft=true}catch{toast('No se pudo conservar el borrador. Exporta una copia.')}}
function scheduleDraftSave(){if(autoSaveTimer)window.clearTimeout?.(autoSaveTimer);if(window.setTimeout&&draftDirty&&s.id&&cloud?.householdId&&!draftConflict)autoSaveTimer=window.setTimeout(()=>{autoSaveTimer=null;void syncDraft();},800);}
function markDraftChanged(){draftDirty=true;draftRevision++;persist();scheduleDraftSave();}
function sameScenarioContent(a,b){const stable=v=>Array.isArray(v)?v.map(stable):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).filter(k=>!['updatedAt','createdAt'].includes(k)).sort().map(k=>[k,stable(v[k])])):v;return JSON.stringify(stable(normalizeScenario(a)))===JSON.stringify(stable(normalizeScenario(b)));}
function applyCloudSnapshot(rows){
 const scope=`${cloud.url}|${cloud.householdId}`,previous=scope===cloudScope?cloudRows:[];cloudScope=scope;cloudRows=rows;hasCloudSnapshot=true;connectionState='connected';cloudSyncError=null;lastSyncedAt=new Date();
 localStore.reconcileCloud(rows,{scope:`${cloud.url}|${cloud.householdId}`,knownIds:previous.map(x=>x.id)});
 selected=new Set([...selected].filter(id=>rows.some(x=>x.id===id)));
 if(s.id){const remote=rows.find(x=>x.id===s.id);if(!remote){if(!draftPendingCreate)draftConflict='deleted';}else{if(legacyDraftUnreviewed){if(!sameScenarioContent(s,remote)){draftDirty=true;draftConflict='changed';}else{s.updatedAt=remote.updatedAt;}legacyDraftUnreviewed=false;persist();}if(remote.updatedAt!==s.updatedAt){if(draftDirty||document.activeElement?.matches?.('#view input, #view select, #view textarea')||document.querySelector('dialog[open]'))draftConflict='changed';else{s=normalizeScenario(copy(remote));draftConflict=null;persist();}}}}
}
async function refreshFamily({quiet=true}={}){
 if(!cloud?.householdId||savingHousing||cloudSavePromise)return;
 if(cloudRefreshPromise)return cloudRefreshPromise;
 const generation=cloudGeneration;
 cloudRefreshPromise=(async()=>{try{const rows=await cloud.list();if(generation!==cloudGeneration)return;applyCloudSnapshot(rows);if(currentView==='viviendas'||currentView==='familia'||((!draftDirty||draftConflict)&&!document.querySelector('dialog[open]')&&!document.querySelector('#view input:focus, #view select:focus, #view textarea:focus')))render();if(!quiet)toast('Lista familiar actualizada.');}catch(error){cloudSyncError=error.message;connectionState='offline';if(!quiet)toast('Sincronización pendiente: '+error.message);if(currentView==='viviendas'||currentView==='familia')render();}})().finally(()=>{cloudRefreshPromise=null;});
 return cloudRefreshPromise;
}
async function syncDraft(){
 if(cloudSavePromise)return cloudSavePromise;
 if(!draftDirty||!s.id||!cloud?.householdId||draftConflict)return;
 if(!hasCloudSnapshot){await refreshFamily();if(!hasCloudSnapshot||draftConflict)return;}
 if(!draftPendingCreate&&!cloudRows.some(x=>x.id===s.id)){draftConflict='deleted';render();return;}
 const candidate=copy(s),revision=draftRevision;if(!calculateScenario(candidate).valid){cloudSyncError='Revisa los campos incompletos o inválidos antes de sincronizar.';return;}cloudGeneration++;
 cloudSavePromise=(async()=>{try{const saved=await cloud.save(candidate,{create:draftPendingCreate,expectedUpdatedAt:candidate.updatedAt});cloudRows=[...cloudRows.filter(x=>x.id!==saved.id),saved];localStore.reconcileCloud(cloudRows,{scope:`${cloud.url}|${cloud.householdId}`});lastSyncedAt=new Date();cloudSyncError=null;connectionState='connected';draftPendingCreate=false;if(s.id===saved.id){if(draftRevision===revision){s=normalizeScenario(saved);draftDirty=false;}else{s.updatedAt=saved.updatedAt;s.createdAt=saved.createdAt;}persist();}if(!document.querySelector('#view input:focus, #view select:focus, #view textarea:focus'))render();}catch(error){cloudSyncError=error.message;if(error.code==='SCENARIO_CONFLICT')draftConflict='changed';else connectionState='offline';persist();render();toast('Los cambios siguen en este dispositivo. '+error.message);}finally{cloudGeneration++;cloudSavePromise=null;if(draftDirty&&!draftConflict&&!cloudSyncError)scheduleDraftSave();}})();return cloudSavePromise;
}
async function flushDraft({switching=false}={}){
 if(autoSaveTimer){window.clearTimeout?.(autoSaveTimer);autoSaveTimer=null;}
 if(cloudSavePromise)await cloudSavePromise;
 if(draftDirty&&s.id&&cloud?.householdId&&!draftConflict)await syncDraft();
 if(draftDirty&&(switching||s.id&&cloud?.householdId))throw Error('El borrador tiene cambios pendientes. Corrígelos o revisa la sincronización antes de abrir otra vivienda; tus datos se conservan.');
}
function syncNotice(){
 if(!cloud?.householdId)return '';
 if(draftConflict&&currentView!=='viviendas')return notice(`<strong>${draftConflict==='deleted'?'Esta vivienda no está en la lista familiar actual.':'Esta vivienda ha cambiado en otro dispositivo.'}</strong> Conservamos tu borrador y no sustituiremos los cambios de tu familia.<div class="inline-actions">${draftConflict==='changed'?'<button class="button secondary" data-action="use-family-version">Abrir versión familiar</button>':''}<button class="button secondary" data-action="draft-as-new">Conservar como vivienda nueva</button><button class="button plain" data-view="viviendas">Ver lista actual</button></div>`,'error');
 return notice(`<strong>${cloudSyncError?'Sincronización pendiente.':draftDirty?'Guardando cambios…':'Lista familiar sincronizada.'}</strong> ${cloudSyncError?'El borrador está conservado en este dispositivo.':'Se actualiza al volver a la ventana y cada 10 segundos mientras está abierta.'}${lastSyncedAt?` <span class="sync-time">Última consulta: ${lastSyncedAt.toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}.</span>`:''} <button class="card-link" data-action="refresh-cloud">Actualizar ahora</button>`,'info');
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000)}
function field(label,path,{hint='',suffix='€',nullable=false,min=0,max,step='any',scale=1,type='number'}={}){const v=get(path);return `<label>${label}${suffix?` <span class="muted">(${suffix})</span>`:''}<input data-field="${path}" data-scale="${scale}" ${nullable?'data-nullable="true"':''} type="${type}" ${type==='number'?`min="${min}" ${max!==undefined?`max="${max}"`:''} step="${step}"`:''} value="${v==null?'':esc(typeof v==='number'?+(v*scale).toFixed(6):v)}" ${nullable?'placeholder="Pendiente"':''}>${hint?`<span class="field-hint">${hint}</span>`:''}</label>`}
function check(label,path,hint=''){return `<label class="check-label"><input type="checkbox" data-field="${path}" ${get(path)?'checked':''}><span>${label}${hint?`<span class="field-hint">${hint}</span>`:''}</span></label>`}
function select(label,path,options,hint=''){return `<label>${label}<select data-field="${path}" ${typeof get(path)==='number'?'data-number="true"':''}>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(get(path))===String(v)?'selected':''}>${l}</option>`).join('')}</select>${hint?`<span class="field-hint">${hint}</span>`:''}</label>`}
const row=(label,value,extra='')=>`<div class="line-item ${extra}"><span>${label}</span><strong>${value}</strong></div>`;
function notice(text,cls=''){return `<div class="notice ${cls}">${text}</div>`}
function section(title,subtitle,body){return `<section class="card form-section"><div class="card-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div></div>${body}</section>`}
function warningSummary(){const pending=result.budget?.incomplete,estimated=(result.budget?.propertyCostsEstimated||result.budget?.assumedLoanTerms);return `<div class="notice ${pending?'':'info'}"><strong>${estimated?'Presupuesto orientativo con provisiones o hipótesis de préstamo.':pending?'Todavía faltan datos para decidir.':'Estimación completa con los datos introducidos.'}</strong> ${estimated?'Los recibos reales pueden ser superiores o inferiores. Completa también las cuotas y primas que falten.':pending?'Las cifras mensuales son el mínimo conocido; completa ingresos, primas y gastos.':'Revisa presupuestos y condiciones antes de comprometer la compra.'}${result.budget?.missingQuotes?.length?`<br>Pendiente: ${esc(result.budget.missingQuotes.join(', '))}.`:''}</div>`}
function resultSidebar(){if(!result.valid)return '';return `<aside class="side-stack sticky"><section class="card side-card"><div class="mini-label">TU SIMULACIÓN AHORA</div><div class="budget-number">${(result.budget.propertyCostsEstimated||result.budget.assumedLoanTerms)?'≈ ':result.budget.incomplete?'≥ ':''}${euro(result.budget.totalMonthly)}<span class="muted" style="font-size:11px;font-weight:400"> /mes</span></div><p>Presupuesto total familiar ${(result.budget.propertyCostsEstimated||result.budget.assumedLoanTerms)?'· orientativo':result.budget.incomplete?'· mínimo conocido':''}</p><div class="breakdown">${row('Solo hipoteca',euro(result.mortgage.monthlyPayment,2))}${row('Préstamo bancario de mamá',euro(result.familyLoan.monthlyPayment,2))}${row('Casa + suministros',euro(result.budget.homeMonthly,2))}${row('Dinero para comprar',euro(result.cash.totalRequired))}${row('Falta por cubrir',euro(result.cash.fundingGap),'total')}</div>${warningSummary()}</section></aside>`}
function summary(){const r=result,b=r.budget,c=r.cash,approx=hasBudgetEstimates(s,r);return `<div class="grid form-layout"><div>
<section class="card"><div class="property-top"><div><div class="house-icon">⌂</div><div><h2>${esc(s.name||'Vivienda sin nombre')}</h2><p>${s.propertyType==='flat'?'Piso':'Casa'}${s.listingDetails?.city?' · '+esc(s.listingDetails.city):''} · ${s.tax.mode==='used'?'Segunda mano · ITP':'Obra nueva · IVA + AJD'}</p></div></div><button class="button secondary" data-action="edit-home">Editar nombre, enlace y fotos</button></div>
${renderPropertyGallery(s.images,s.name,esc)}<div class="price-row"><div><span class="mini-label">PRECIO DEL ANUNCIO</span><div class="housing-price">${euro(s.purchasePrice)}</div></div><div><button class="card-link" data-view="compra">Editar precio e impuestos →</button></div></div>
<div class="purchase-strip"><div><small>Hipoteca</small><strong>${euro(r.mortgage.principal)}</strong></div><div><small>${s.tax.mode==='used'?'ITP':'IVA + AJD'} estimado</small><strong>${euro(r.tax.total)}</strong></div><div><small>Préstamo de mamá</small><strong>${euro(r.familyLoan.principal)}</strong></div></div>
${s.url?`<a class="card-link" href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">Abrir anuncio original ↗</a>`:''}${s.notes?`<div class="notice info">${esc(s.notes)}</div>`:''}</section>
${renderFinancingBreakdown(s,r,{euro,pct,notice,row,compact:true})}
${renderRentalComparison(s,r,{euro,esc})}
${renderBorrowerDebt(s,r,{euro,pct,notice,row,esc})}
<div class="metric-grid"><section class="metric-card"><div class="label">Solo hipoteca · componente del total</div><div class="metric-value">${euro(r.mortgage.monthlyPayment,2)} <small>/mes</small></div><p>Capital e intereses. ${s.mortgage.years} años al ${num(r.mortgage.rate)} % TIN.</p></section><section class="metric-card"><div class="label">Préstamo bancario de mamá · componente del total</div><div class="metric-value">${r.familyLoan.termsAssumed?'≈ ':''}${euro(r.familyLoan.monthlyPayment,2)} <small>/mes</small></div><p>${r.familyLoan.termsAssumed?'Hipótesis editable: ':'Condiciones introducidas: '}${s.familyLoan.years??'plazo pendiente'} años · ${s.familyLoan.rate??'TIN pendiente'} % TIN. Se cuenta una vez.</p></section></div>
<section class="card"><h2>Dinero necesario para comprar</h2><p>Mamá cubre lo que no financian la hipoteca y el ICF: impuestos, gastos y colchón. Las arras son un anticipo del precio y requieren dinero antes de la firma.</p><div class="breakdown">${row('Aportación al precio fuera de hipoteca / ICF',euro(c.priceContribution))}${row('Impuestos de compraventa',euro(r.tax.total))}${row('Gastos de compra, seguros iniciales y reformas',euro(c.totalRequired-c.priceContribution-r.tax.total-(c.totalReserve??c.reserve)))}${row('Colchón adicional del préstamo de mamá',euro(c.familyExtraBuffer||0))}${row('Otro colchón reservado',euro(c.reserve))}${row('Total necesario fuera de hipoteca / ICF',euro(c.totalRequired),'total')}${row('Ahorro disponible',euro(c.savings))}${row('Préstamo de mamá · máximo 60.000 €',euro(r.familyLoan.principal))}${row('Falta por cubrir',euro(c.fundingGap),'total')}</div>${c.purchaseFees===0?notice('Todavía faltan los presupuestos de tasación, notaría, registro y asesoría. El préstamo calculado aumentará al introducirlos; los importes a cero no significan que sean gratuitos.'):''}
${r.familyLoan.termsAssumed?notice(`El préstamo se calcula con una hipótesis del ${num(s.familyLoan.rate)} % TIN a ${num(s.familyLoan.years)} años, editable y pendiente de oferta. Se dimensiona para la parte del precio que quede sin financiar, impuestos y gastos introducidos, más el colchón extra, con tope de 60.000 €. El límite es de importe; su concesión sigue pendiente del banco.`,'info'):''}
<div class="flow"><div class="flow-step"><small>ANTES DE LA FIRMA</small><h3>Arras y comprobaciones</h3><div class="amount">${euro(c.beforeMortgageRequired)}</div><p>${c.beforeMortgageGap?'Faltan '+euro(c.beforeMortgageGap)+' disponibles en esta fase.':'Según la disponibilidad indicada.'}</p></div><div class="flow-step"><small>EN LA ESCRITURA</small><h3>Completar la compra</h3><div class="amount">${euro(Math.max(0,c.closingNetPayment))}</div><p>Aportación neta restante al firmar.${c.potentialClosingSurplus>0?' El modelo arroja fondos superiores al pago restante: confirmad el circuito de las arras; no es un reembolso garantizado.':''}</p></div><div class="flow-step"><small>DESPUÉS</small><h3>Reformas y colchón</h3><div class="amount">${euro(c.renovations+(c.totalReserve??c.reserve))}</div><p>El colchón se conserva como efectivo; no es un gasto de adquisición.</p></div></div><button class="card-link" data-view="compra">Revisar todos los costes de compra →</button></section>
<section class="card"><h2>Margen mensual del hogar</h2><div class="budget-number">${b.actualRegularIncome?(approx?'≈ ':b.incomplete?'≤ ':'')+euro(b.remainingRegular,2):'Faltan ingresos'}</div><p>Después del presupuesto familiar introducido. ${b.incomplete?'Faltan datos para decidir.':''}</p><div class="breakdown">${row('Ingresos ordinarios del hogar',euro(b.actualRegularIncome,2))}${row('Ingresos de los dos titulares',euro(b.regularIncome,2))}${row('Esfuerzo de los titulares',(b.borrowerDebtRatioIncomplete?'≥ ':'')+pct(b.debtRatio))}${row('Deudas / ingresos del hogar',pct(b.familyDebtRatio))}</div></section>
${warningSummary()}<details><summary>Revisar todos los avisos (${r.warnings.length})</summary><div class="notice"><ul class="warning-list">${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div></details>
</div>${resultSidebar()}</div>`}
